<?php header('Content-Type: application/json');require __DIR__.'/../includes/db.php';$code=strtoupper(trim($_GET['order_code']??''));if(!$code){http_response_code(400);echo json_encode(['error'=>'order_code is required']);exit;}$pdo=get_db();$st=$pdo->prepare('SELECT id,order_code,buyer_name,total,status,created_at FROM orders WHERE order_code=?');$st->execute([$code]);$o=$st->fetch();if(!$o){http_response_code(404);echo json_encode(['error'=>'Order not found']);exit;}$st=$pdo->prepare('SELECT status,note,created_at FROM order_status_log WHERE order_id=? ORDER BY id');$st->execute([$o['id']]);echo json_encode(['order_code'=>$o['order_code'],'buyer_name'=>$o['buyer_name'],'total'=>(float)$o['total'],'latest_status'=>$o['status'],'history'=>$st->fetchAll()]);